void
mrb_init_range(mrb_state *mrb)
{
  struct RClass *r;

  r = mrb_define_class_id(mrb, MRB_SYM(Range), mrb->object_class);                                /* 15.2.14 */
  mrb->range_class = r;
  MRB_SET_INSTANCE_TT(r, MRB_TT_RANGE);

  MRB_MT_INIT_ROM(mrb, r, range_rom_entries);
}

